/*
 * Resurgence AI: research engine
 * Shared by the dashboard (index.html) and the daily script (scripts/daily-research.mjs).
 *
 * Data tiers used everywhere:
 *   VERIFIED   = returned by the YouTube Data API v3 (views, likes, comments, dates, titles, links, subs)
 *   CALCULATED = arithmetic on verified data (VPH, channel baselines, breakout multiples, topic heat)
 *   PREDICTION = generated by this engine (ideas, titles, thumbnail concepts, opportunity scores, verdicts)
 */
(function (root) {
  'use strict';

  const API = 'https://www.googleapis.com/youtube/v3/';
  const COST = { search: 100, channels: 1, playlistItems: 1, videos: 1 };
  const HOUR = 3600e3, DAY = 24 * HOUR;

  const DEFAULT_CONFIG = {
    // @handles resolve exactly for 1 quota unit each
    competitors: [{ input: '@devised_' }, { input: '@klawYT' }, { input: '@Lionxo' }, { input: '@s6intx' }, { input: '@arznwz' }],
    queries: [
      { q: 'rebirth island', order: 'viewCount', hours: 168 },
      { q: 'rebirth island', order: 'date', hours: 48 },
      { q: 'warzone resurgence', order: 'viewCount', hours: 168 },
      { q: 'rebirth island meta', order: 'viewCount', hours: 168 },
      { q: 'warzone meta loadout', order: 'viewCount', hours: 168 },
      { q: 'warzone best smg', order: 'viewCount', hours: 168 },
      { q: 'warzone movement', order: 'viewCount', hours: 168 },
      { q: 'warzone controller settings', order: 'viewCount', hours: 168 },
      { q: 'warzone ranked', order: 'viewCount', hours: 168 },
      { q: 'warzone sniper', order: 'viewCount', hours: 168 }
    ],
    // One weapon per line. Add aliases after "|" (e.g. "KAR98K|KAR98|KAR 98"). Keep in sync with the current season.
    weapons: ['VEL-46', 'X-58 NYX|X-58|NYX', 'M4 Hurricane', 'FSS Hurricane', 'Kastov-762', 'Kastov 545', 'PPSh|PPSH-41|PPSh-41',
      'AK-74u|AK74u', 'M4A1', '141 Prime M4|141 Prime', 'ISO Nightshade|Nightshade', 'ISO SMG', 'Cronen Osprey|Osprey', 'Striga',
      'FJX Horus|Horus', 'FJX Imperium|Imperium', 'KAR98K|KAR98|KAR 98', 'Mosin|Mosin Nagant', 'MCW 6.8|MCW', 'Astaroth .57|Astaroth',
      'Signal 50', 'Desert Eagle SMG|Desert Eagle', 'MP5', 'MP7', 'PP-919', 'MPC-25', 'VMP', 'VST', 'MAC-10', 'KSV', 'OTS-9', 'HRM-9',
      'P90', 'Superi-46|Superi', 'Glock', 'Welgun', 'MP-40', 'Tommy Gun', 'AN-94', 'REV-46', 'Draco', 'Blixen', 'Uzi', 'Ryden 45K|Ryden',
      'ARP', 'TR51 Para|TR51', 'Sturmwolf', 'RK-9', 'Dravec-45|Dravec', 'Peacekeeper', 'Striker'],
    relevance: 'warzone|rebirth|resurgence|\\bmw4\\b|hajin|haunted hollow|verdansk|call of duty|\\bcod\\b',
    exclude: 'warzone mobile|cod mobile|benchmark|\\brtx\\b|dlss|\\bdmz\\b|highlights|funny moments|1440p',
    resurgenceTerms: 'rebirth|resurgence|haunted hollow|fortune|ashika|vondel',
    focus: ['high-kill', 'movement', 'meta-loadout', 'smg', 'rebirth', 'settings', 'ranked'],
    breakoutRatio: 3,          // flag when views >= 3x the channel's age-adjusted norm
    minBreakoutViews: 2000,    // ignore tiny absolute numbers
    decayDays: 4,              // age adjustment: expected share of mature views = 1 - exp(-ageDays / decayDays)
    smallCreatorMaxSubs: 150000,
    saturationChannels: 8,     // distinct uploaders in 48h at which a topic counts as crowded
    shortMaxSeconds: 180,
    maxDiscoveredChannels: 120, // channels from search results whose uploads are fetched for baselines (2 units each)
    includeShorts: false,
    resurgenceOnly: false,
    regionCode: 'US',
    relevanceLanguage: 'en'
  };

  const TOPICS = [
    { id: 'rebirth', label: 'Rebirth Island', re: /rebirth|resurgence/i },
    { id: 'high-kill', label: 'High-kill gameplay', re: /\b\d{2,3}\s*\+?\s*kills?\b|personal record|\bnuke\b|high[\s-]?kill/i },
    { id: 'meta-loadout', label: 'Meta loadouts', re: /\bmeta\b|loadout|\bbuild\b|\bclass\b|gunsmith/i },
    { id: 'smg', label: 'SMG meta', re: /\bsmgs?\b/i },
    { id: 'sniper', label: 'Sniper / one-shot', re: /sniper|one shot|1 shot|kar ?98|mosin|ghillie|signal 50|astaroth/i },
    { id: 'movement', label: 'Movement', re: /movement|speed hack|ankle break|\bslide|b-?hop|bunny hop/i },
    { id: 'settings', label: 'Settings & sensitivity', re: /settings|sensitivity|\bsens\b|aim assist|dead ?zone/i },
    { id: 'ranked', label: 'Ranked', re: /ranked/i },
    { id: 'launch', label: 'Season / update news', re: /(warzone|rebirth island) is (finally )?here|is (finally )?here|season \d|\bupdate|\bpatch|\bnerf|\bbuff|last days/i },
    { id: 'swap', label: '“Goodbye X, Hello Y” format', re: /goodbye .+hello/i },
    { id: 'input', label: 'Controller vs keyboard', re: /keyboard|\bkbm\b|controller players|outaiming controller|controller vs/i },
    { id: 'challenge', label: 'Challenges & kill races', re: /\bonly\b|challenge|kill race|\b\d\s?v\s?\d\b/i }
  ];
  const TOPIC_BY_ID = Object.fromEntries(TOPICS.map(t => [t.id, t]));
  // These describe nearly every video in the niche, so they are never "saturated" and aren't shown as today's specific trends.
  const UMBRELLA = ['rebirth', 'meta-loadout', 'high-kill'];

  const CODE_RE = /\b([A-Z]{1,4}[- ]?\d{1,3}[A-Z]?)\b/g;
  const CODE_EXCLUDE = /^(MW\d*|BO\d*|WZ\d*|PS\d|S\d{1,2}|SZN\d*|V\d|XB\d*|COD\d*|TOP\d+|GTA\d*|FPS\d*|RTX\d+|GTX\d+|FOV\d*|HDR\d*|DAY\d+|PT\d+|EP\d+|NO\d+|K\d|X\d|[A-Z]?4K|1V\d|2V\d|3V\d|4V\d|TOP|AND\d*)$/;

  // ---------- small utils ----------
  const clamp = (x, a = 0, b = 1) => Math.max(a, Math.min(b, x));
  const median = a => { if (!a.length) return null; const s = [...a].sort((x, y) => x - y); const m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
  const chunk = (a, n) => { const out = []; for (let i = 0; i < a.length; i += n) out.push(a.slice(i, i + n)); return out; };
  const uniq = a => [...new Set(a)];
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  function fmtNum(n) { if (n == null || isNaN(n)) return '–'; const a = Math.abs(n); if (a >= 1e6) return (n / 1e6).toFixed(a >= 1e7 ? 0 : 1) + 'M'; if (a >= 1e3) return (n / 1e3).toFixed(a >= 1e4 ? 0 : 1) + 'K'; return String(Math.round(n)); }
  function fmtAge(h) { if (h < 1) return Math.max(1, Math.round(h * 60)) + 'm'; if (h < 48) return Math.round(h) + 'h'; return Math.round(h / 24) + 'd'; }
  function parseDuration(iso) { const m = /P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/.exec(iso || ''); if (!m) return 0; return (+m[1] || 0) * 86400 + (+m[2] || 0) * 3600 + (+m[3] || 0) * 60 + (+m[4] || 0); }
  const norm = s => s.toLowerCase().replace(/[^a-z0-9]/g, '');

  function mergeConfig(c) { return Object.assign({}, DEFAULT_CONFIG, c || {}); }

  // ---------- YouTube API client ----------
  class YTError extends Error { constructor(msg, status, reason) { super(msg); this.status = status; this.reason = reason; } }

  function makeClient(apiKey, state) {
    return async function yt(endpoint, params) {
      const qs = new URLSearchParams({ ...params, key: apiKey });
      let res, body;
      try { res = await fetch(API + endpoint + '?' + qs); body = await res.json(); }
      catch (e) { throw new YTError('Network error calling YouTube API: ' + e.message, 0, 'network'); }
      state.quota += COST[endpoint] || 1;
      state.calls++;
      if (!res.ok || body.error) {
        const err = body.error || {};
        const reason = (err.errors && err.errors[0] && err.errors[0].reason) || '';
        throw new YTError(err.message || ('HTTP ' + res.status), res.status, reason);
      }
      return body;
    };
  }


  // ---------- text analysis ----------
  function compileWeapons(list) {
    return (list || []).filter(Boolean).map(line => {
      const names = String(line).split('|').map(s => s.trim()).filter(Boolean);
      const res = names.map(n => {
        const parts = n.split(/[\s\-.]+/).filter(Boolean).map(p => p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
        return new RegExp('(^|[^a-z0-9])' + parts.join('[\\s\\-.]*') + '(?![a-z0-9])', 'i');
      });
      return { name: names[0], key: norm(names[0]), aliasKeys: names.map(norm), res };
    });
  }
  function detectWeapons(title, compiled) {
    const found = new Map();
    for (const w of compiled) if (w.res.some(re => re.test(title))) found.set(w.key, w);
    const out = [...found.values()].map(w => w.name);
    const known = [...found.values()].flatMap(w => w.aliasKeys);
    let m; CODE_RE.lastIndex = 0;
    while ((m = CODE_RE.exec(title))) {
      const raw = m[1].replace(' ', '-'), flat = raw.replace('-', '');
      if (CODE_EXCLUDE.test(flat) || /^\d/.test(flat) || !/\d/.test(flat)) continue;
      const after = title.slice(m.index + m[0].length, m.index + m[0].length + 7);
      if (/^\s*(kills?|wins?|sens|fps)/i.test(after)) continue;
      const k = norm(raw);
      if (!known.some(fk => fk === k || fk.startsWith(k) || k.startsWith(fk))) { out.push(raw); known.push(k); }
    }
    return out;
  }
  function detectTopics(text) { return TOPICS.filter(t => t.re.test(text)).map(t => t.id); }
  function detectKills(title) { const m = /\b(\d{2,3})\s*\+?\s*kills?\b/i.exec(title); return m ? +m[1] : null; }
  const GOODBYE_RE = /goodbye\s+([^,]+?)\s*(?:meta)?\s*,\s*hello\s+(?:new\s+)?(.+?)\s+(?:meta|in|on)\b/i;

  // ---------- baselines & breakout math ----------
  function expectedFraction(ageHours, decayDays) { return Math.max(0.05, 1 - Math.exp(-(ageHours / 24) / decayDays)); }

  function computeBaseline(uploads, now, shortMax, wantShort) {
    const pool = uploads.filter(v => (v.durationSec <= shortMax) === wantShort && v.views != null);
    const age = v => (now - Date.parse(v.publishedAt)) / HOUR;
    let mature = pool.filter(v => age(v) >= 168);
    let type = 'median of uploads 7+ days old';
    if (mature.length < 4) { mature = pool.filter(v => age(v) >= 72); type = 'median of uploads 3+ days old (few uploads)'; }
    if (mature.length < 3) return null;
    return { value: median(mature.map(v => v.views)), n: mature.length, type };
  }

  // ---------- RESEARCH (network) ----------
  async function research({ apiKey, config, onProgress = () => {}, now = Date.now() }) {
    const cfg = mergeConfig(config);
    const state = { quota: 0, calls: 0 };
    const yt = makeClient(apiKey, state);
    const errors = [];
    const relRe = new RegExp(cfg.relevance, 'i'); // the exclude list is applied to titles in analyze()
    const step = (msg) => onProgress({ msg, quota: state.quota });

    // 1. resolve competitors
    step('Resolving tracked channels');
    const competitors = [];
    for (const c of cfg.competitors) {
      const out = { ...c };
      try {
        if (c.id) { competitors.push(out); continue; }
        const input = String(c.input || '').trim();
        let m;
        if ((m = /(UC[\w-]{22})/.exec(input))) { out.id = m[1]; out.matchedBy = 'channel id'; out.status = 'verified'; }
        else if ((m = /(?:youtube\.com\/)?@([\w.\-]+)/.exec(input)) && input.includes('@')) {
          const r = await yt('channels', { part: 'id', forHandle: '@' + m[1] });
          if (r.items && r.items[0]) { out.id = r.items[0].id; out.matchedBy = 'handle @' + m[1]; out.status = 'verified'; }
          else { out.status = 'not found'; }
        } else if (input) {
          const r = await yt('search', { part: 'snippet', type: 'channel', q: input + ' warzone', maxResults: 5 });
          const items = r.items || [];
          const exact = items.find(i => norm(i.snippet.channelTitle) === norm(input)) || items.find(i => norm(i.snippet.channelTitle).includes(norm(input)));
          const pick = exact || items[0];
          if (pick) { out.id = pick.snippet.channelId || pick.id.channelId; out.matchedBy = 'search "' + input + ' warzone"'; out.status = exact ? 'auto-matched' : 'weak match: please confirm'; }
          else out.status = 'not found';
        }
      } catch (e) { out.status = 'error'; errors.push(`Resolve "${c.input}": ${e.message}`); if (e.reason === 'quotaExceeded') throw Object.assign(e, { partial: true }); }
      competitors.push(out);
    }
    const trackedIds = uniq(competitors.filter(c => c.id).map(c => c.id));

    // 2. niche-wide search
    const searchHits = new Map(); // videoId -> [query labels]
    for (const q of cfg.queries) {
      step(`Searching YouTube: "${q.q}" (${q.order}, last ${q.hours}h)`);
      try {
        const r = await yt('search', {
          part: 'snippet', type: 'video', q: q.q, order: q.order, maxResults: 50,
          publishedAfter: new Date(now - q.hours * HOUR).toISOString(),
          regionCode: cfg.regionCode, relevanceLanguage: cfg.relevanceLanguage
        });
        for (const it of r.items || []) {
          const id = it.id && it.id.videoId; if (!id) continue;
          if (!searchHits.has(id)) searchHits.set(id, []);
          searchHits.get(id).push(`${q.q} · ${q.order}`);
        }
      } catch (e) { errors.push(`Search "${q.q}": ${e.message}`); if (e.reason === 'quotaExceeded') break; }
    }

    // 3. video details for search hits
    const videos = new Map();
    async function fetchVideos(ids) {
      for (const group of chunk(ids.filter(id => !videos.has(id)), 50)) {
        const r = await yt('videos', { part: 'snippet,statistics,contentDetails', id: group.join(','), maxResults: 50 });
        for (const v of r.items || []) {
          const s = v.statistics || {}, sn = v.snippet || {};
          videos.set(v.id, {
            id: v.id, title: sn.title, channelId: sn.channelId, channelTitle: sn.channelTitle,
            publishedAt: sn.publishedAt, description: (sn.description || '').slice(0, 300), tags: (sn.tags || []).slice(0, 15),
            views: s.viewCount != null ? +s.viewCount : null, likes: s.likeCount != null ? +s.likeCount : null,
            comments: s.commentCount != null ? +s.commentCount : null,
            durationSec: parseDuration(v.contentDetails && v.contentDetails.duration),
            live: sn.liveBroadcastContent && sn.liveBroadcastContent !== 'none',
            thumb: (sn.thumbnails && (sn.thumbnails.medium || sn.thumbnails.default) || {}).url || null
          });
        }
      }
    }
    step('Fetching video statistics');
    try { await fetchVideos([...searchHits.keys()]); } catch (e) { errors.push('Video details: ' + e.message); }

    const relevantSearch = [...searchHits.keys()].map(id => videos.get(id)).filter(v => v && relRe.test(v.title + ' ' + v.tags.join(' ') + ' ' + v.description));
    const discovered = uniq(relevantSearch.map(v => v.channelId)).filter(id => !trackedIds.includes(id));

    // 4. channel details (tracked + discovered)
    step('Fetching channel statistics');
    const channels = {};
    const allChannelIds = uniq([...trackedIds, ...discovered]);
    try {
      for (const group of chunk(allChannelIds, 50)) {
        const r = await yt('channels', { part: 'snippet,statistics,contentDetails', id: group.join(','), maxResults: 50 });
        for (const c of r.items || []) {
          const st = c.statistics || {};
          channels[c.id] = {
            id: c.id, title: c.snippet.title, handle: c.snippet.customUrl || null,
            thumb: (c.snippet.thumbnails && (c.snippet.thumbnails.default || {}).url) || null,
            subs: st.hiddenSubscriberCount ? null : (st.subscriberCount != null ? +st.subscriberCount : null),
            viewCount: +st.viewCount || 0, videoCount: +st.videoCount || 0,
            uploads: c.contentDetails && c.contentDetails.relatedPlaylists && c.contentDetails.relatedPlaylists.uploads,
            tracked: trackedIds.includes(c.id), uploadIds: []
          };
        }
      }
    } catch (e) { errors.push('Channel details: ' + e.message); }
    for (const c of competitors) if (c.id && channels[c.id]) c.title = channels[c.id].title;

    // 5. recent uploads per channel -> baselines (tracked first, then discovered by relevance volume)
    const discoveredRanked = discovered.sort((a, b) => relevantSearch.filter(v => v.channelId === b).length - relevantSearch.filter(v => v.channelId === a).length).slice(0, cfg.maxDiscoveredChannels);
    const uploadTargets = [...trackedIds, ...discoveredRanked].filter(id => channels[id] && channels[id].uploads);
    let i = 0;
    for (const id of uploadTargets) {
      i++;
      if (i % 10 === 1) step(`Reading recent uploads for channel baselines (${i}/${uploadTargets.length})`);
      try {
        const r = await yt('playlistItems', { part: 'contentDetails', playlistId: channels[id].uploads, maxResults: 50 });
        const ids = (r.items || []).map(it => it.contentDetails.videoId);
        channels[id].uploadIds = ids;
        await fetchVideos(ids);
      } catch (e) {
        if (e.status !== 404) errors.push(`Uploads for ${channels[id].title}: ${e.message}`);
        if (e.reason === 'quotaExceeded') break;
      }
    }
    for (const id of Object.keys(channels)) {
      const ch = channels[id];
      const ups = ch.uploadIds.map(v => videos.get(v)).filter(Boolean).filter(v => !v.live);
      ch.baselineLong = computeBaseline(ups, now, cfg.shortMaxSeconds, false);
      ch.baselineShort = computeBaseline(ups, now, cfg.shortMaxSeconds, true);
      if (!ch.baselineLong && ch.videoCount) ch.baselineProxy = { value: ch.viewCount / ch.videoCount, n: ch.videoCount, type: 'lifetime average (weak proxy)' };
    }

    // 6. keep: search hits (relevant) + all tracked uploads from the last 30 days
    const keep = new Map();
    for (const v of relevantSearch) keep.set(v.id, { ...v, sources: searchHits.get(v.id), relevant: true });
    for (const id of trackedIds) for (const vid of (channels[id] && channels[id].uploadIds) || []) {
      const v = videos.get(vid);
      if (v && now - Date.parse(v.publishedAt) < 30 * DAY) {
        const prev = keep.get(vid);
        keep.set(vid, { ...v, sources: [...(prev ? prev.sources : []), 'tracked channel'], relevant: relRe.test(v.title + ' ' + v.tags.join(' ') + ' ' + v.description) });
      }
    }
    for (const ch of Object.values(channels)) delete ch.uploads;

    step('Done');
    return {
      version: 1, researchedAt: new Date(now).toISOString(), quotaUsed: state.quota, apiCalls: state.calls,
      errors, competitors, channels, videos: [...keep.values()], configUsed: { queries: cfg.queries }
    };
  }


  // ---------- ANALYSIS (pure, no network) ----------
  function prevSnapshot(history, nowMs) {
    const older = (history || []).filter(s => nowMs - Date.parse(s.at) >= 12 * HOUR).sort((a, b) => Date.parse(b.at) - Date.parse(a.at));
    return older[0] || null;
  }

  // Momentum: how strongly the last 48h of uploads beat their own channels' norms, vs uploads from 2–7 days ago.
  // Uses averages of age-adjusted multiples, so it isn't skewed by how many old vs new videos the searches returned.
  function momentumOf(vids) {
    const mean = a => a.reduce((s, x) => s + x, 0) / a.length;
    const fresh = vids.filter(v => v.ageHours >= 3 && v.ageHours <= 48 && v.ratio != null).map(v => Math.min(v.ratio, 10));
    const older = vids.filter(v => v.ageHours > 48 && v.ageHours <= 168 && v.ratio != null).map(v => Math.min(v.ratio, 10));
    if (!fresh.length) return { m: 0.6, quiet: true };
    return { m: (mean(fresh) + 0.5) / ((older.length ? mean(older) : 1) + 0.5), quiet: false };
  }
  const momentumLabel = (m, quiet) => quiet ? 'Quiet' : m >= 1.25 ? 'Rising' : m >= 0.8 ? 'Steady' : 'Cooling';

  function groupStats(vids, cfg, channels, umbrella) {
    const recent = vids.filter(v => v.ageHours <= 168);
    const c24 = recent.filter(v => v.ageHours <= 24), c48 = recent.filter(v => v.ageHours <= 48);
    const ch48 = uniq(c48.map(v => v.channelId)).length;
    const heat = recent.reduce((s, v) => s + Math.min(v.ratio ?? 1, 10) * Math.exp(-(v.ageHours / 24) / 5), 0);
    const { m, quiet } = momentumOf(recent);
    const sorted = [...recent].sort((x, y) => (y.ratio ?? 0) - (x.ratio ?? 0));
    const breakouts = recent.filter(v => v.breakout);
    const small = breakouts.filter(v => { const s = channels[v.channelId] && channels[v.channelId].subs; return s != null && s <= cfg.smallCreatorMaxSubs; });
    return {
      n7: recent.length, n48: c48.length, n24: c24.length, ch48, ch7: uniq(recent.map(v => v.channelId)).length,
      views7: recent.reduce((s, v) => s + (v.views || 0), 0), heat: +heat.toFixed(2), momentum: +m.toFixed(2),
      momentumLabel: momentumLabel(m, quiet), breakouts: breakouts.length, smallBreakouts: small.length,
      evidence: median(sorted.slice(0, 3).map(v => v.ratio).filter(x => x != null)) || 0,
      saturated: !umbrella && ch48 >= cfg.saturationChannels && m < 1.1,
      competition: ch48 >= cfg.saturationChannels * 0.75 ? 'High' : ch48 >= cfg.saturationChannels * 0.35 ? 'Medium' : 'Low',
      top: sorted.slice(0, 6).map(v => v.id)
    };
  }

  function trendPhase(series) {
    if (series.length < 3) return { phase: 'Needs 3+ days of history', code: 'na' };
    const last = series[series.length - 1], prev = series[series.length - 2], prev2 = series[series.length - 3];
    const max = Math.max(...series);
    if (last >= prev * 1.15) return { phase: 'Rising', code: 'up' };
    if (last <= prev * 0.85) return { phase: series.slice(-4).includes(max) ? 'Peaked, now declining' : 'Declining', code: 'down' };
    if (last >= 0.9 * max && prev >= prev2 * 1.1) return { phase: 'Peaking', code: 'peak' };
    return { phase: 'Flat', code: 'flat' };
  }

  // ---- templates (PREDICTION). XX = your own kill count. ----
  const TITLE_TEMPLATES = {
    'meta-loadout': ['XX Kills w/ the {W} Meta on Rebirth Island 👑', 'This {W} Is Actually BROKEN on Rebirth Island', 'Goodbye {OLD}, Hello {W} Meta on Rebirth Island 👑', 'The PERFECT {W} Loadout for Resurgence 👑', 'The NEW #1 {W} Meta on Rebirth Island'],
    'high-kill': ['XX Kills w/ the {W} Meta on Rebirth Island 👑', 'My HIGHEST Kill Game on Rebirth Island 👑', '{W} = AIMBOT on Rebirth Island'],
    'rebirth': ['The PERFECT Game on Rebirth Island 👑', 'XX Kills on Rebirth Island w/ the {W} 👑', 'The {W} Is BROKEN on Rebirth Island'],
    smg: ['The FASTEST SMG META on Rebirth Island 👑', 'XX Kills w/ the FASTEST {W} SMG on Rebirth Island 👑', 'This SMG Is Actually BROKEN on Rebirth Island'],
    sniper: ['The ONE SHOT {W} Meta on Rebirth Island 👑', 'XX Kills w/ the {W} SNIPER on Rebirth Island 👑', 'This SNIPER Is Actually BROKEN on Rebirth Island'],
    movement: ['The FASTEST Movement on Rebirth Island 👑', 'XX Kills w/ SPEED HACK Movement on Rebirth Island 👑', 'This {W} Movement Makes You UNKILLABLE on Rebirth Island', 'Low Sens = PERFECT Movement on Rebirth Island 👑'],
    settings: ['Low Sens = AIMBOT on Rebirth Island 👑', 'XX Kills on Rebirth Island 👑 + FULL Settings', 'My NEW Controller Settings for Resurgence'],
    ranked: ['The #1 RANKED Loadout for Rebirth Island Right Now 👑', 'XX Kills in RANKED Resurgence w/ the {W} 👑', 'How I Climb RANKED on Rebirth Island (Full Loadout)'],
    launch: ['Rebirth Island Is PERFECT Right Now 👑', 'Everything NEW in Resurgence This Season 👑', 'The NEW Season Meta on Rebirth Island 👑'],
    swap: ['Goodbye {OLD}, Hello {W} Meta on Rebirth Island 👑', 'Goodbye {OLD}, Hello NEW #1 Meta on Rebirth Island 👑'],
    input: ['Controller vs Keyboard on Rebirth Island: Who Really WINS?', 'I Outplayed KBM Players on Controller 👑', 'Low Sens Controller vs KBM on Rebirth Island'],
    challenge: ['I Used ONLY the {W} on Rebirth Island 👑', 'Can I Drop XX Kills w/ ONLY the {W}?', 'The HARDEST Challenge on Rebirth Island']
  };
  const THUMB_TEMPLATES = {
    'meta-loadout': 'The {W} large and angled across a dark Rebirth backdrop, big yellow "XX KILLS" with black stroke, crown icon top corner.',
    'high-kill': 'Mid-fight frame, huge "XX KILLS" in yellow with black stroke, the {W} cut out on the right, crown icon.',
    rebirth: 'Prison block behind you, "XX KILLS" big, the {W} on the right.',
    smg: 'The {W} with speed lines, "FASTEST TTK" in yellow, crown icon.',
    sniper: 'Scope view with a hit marker, "ONE SHOT" in yellow, the {W} cut out on the right.',
    movement: 'Mid-slide action frame with motion blur, bright arrow tracing your path, 2-word text "TOO FAST".',
    settings: 'Controller close-up with your real sensitivity numbers overlaid, "LOW SENS = AIMBOT".',
    ranked: 'Your ranked badge large on the left, the {W} on the right, "#1 RANKED" text.',
    launch: 'New Rebirth Island skyline, red "NEW" badge, short text naming the change.',
    swap: 'Old gun greyed out with a red X on the left, the {W} glowing on the right, "GOODBYE / HELLO" labels.',
    input: 'Split frame: controller vs keyboard, "WHO WINS?" across the middle.',
    challenge: 'The {W} with a red "ONLY" stamp, kill counter in the corner.'
  };
  const IDEA_TEMPLATES = {
    'meta-loadout': 'High-kill Rebirth Island game with the {W} meta: show the build first, then the kills',
    'high-kill': 'High-kill Rebirth Island game with the {W}, edited tight around the best fights',
    rebirth: 'Full Rebirth Island game with the {W} and your current meta',
    smg: 'Fastest-killing SMG setup ({W}) in a long-form Rebirth Island game',
    sniper: 'One-shot sniper ({W}) Rebirth Island game with the loadout explained',
    movement: 'Fast-movement Rebirth Island game: the techniques, then a full high-kill game using them',
    settings: 'Your exact controller settings (sens, deadzones, aim assist) plus a gameplay proof',
    ranked: 'Ranked Resurgence game with your #1 ranked loadout ({W})',
    launch: 'What changed in Resurgence this season, tested in a real game',
    swap: 'Meta-swap video: why the {W} replaces the old pick, then a high-kill game',
    input: 'Controller vs keyboard on Rebirth Island, with your settings and clips as evidence',
    challenge: '{W}-only Rebirth Island challenge with a kill target'
  };
  const CAPS_WORDS = /^[A-Z#][A-Z0-9#'!*]{2,}$/;

  function tokenSet(t) { return new Set(String(t).toLowerCase().replace(/[^a-z0-9# ]/g, ' ').split(/\s+/).filter(w => w.length > 2 && !['the', 'and', 'with', 'for', 'this', 'that', 'you', 'your', 'are', 'was', 'its', 'meta'].includes(w))); }
  function jaccard(a, b) { let inter = 0; for (const x of a) if (b.has(x)) inter++; return inter / (a.size + b.size - inter || 1); }

  /** Transparent title score (0–100). ctx: {trendingWeapons, risingTopics, breakoutTitles, realTitles, compiledWeapons} */
  function scoreTitle(title, ctx) {
    title = String(title || '').trim();
    const parts = [];
    const len = [...title].length;
    parts.push({ k: 'Length', max: 15, pts: len >= 35 && len <= 60 ? 15 : len >= 25 && len <= 70 ? 8 : 0, why: `${len} characters (35–60 avoids cut-off on phones)` });
    const niche = /warzone|rebirth|resurgence/i.test(title);
    parts.push({ k: 'Niche keyword', max: 15, pts: niche ? 15 : 0, why: niche ? 'names Rebirth / Resurgence / Warzone' : 'no Rebirth / Resurgence / Warzone keyword, so search can’t match it' });
    const hasNum = /\b(\d{2,3}|XX)\s*\+?\s*kills?\b/i.test(title) || /\b\d+\b/.test(title);
    const weapons = ctx.compiledWeapons ? detectWeapons(title, ctx.compiledWeapons) : [];
    parts.push({ k: 'Specific hook', max: 15, pts: (hasNum ? 8 : 0) + (weapons.length ? 7 : 0), why: [hasNum ? 'has a number/kill count' : 'no number', weapons.length ? 'names a weapon' : 'no weapon'].join(', ') });
    const words = title.split(/\s+/), caps = words.filter(w => CAPS_WORDS.test(w.replace(/[^\w#'!*]/g, '')) && w !== 'XX' && !/^\d/.test(w)).length;
    const allCaps = caps >= words.length - 1 && words.length > 3;
    parts.push({ k: 'Emphasis', max: 10, pts: allCaps ? 0 : caps >= 1 && caps <= 3 ? 10 : caps > 3 ? 4 : 0, why: allCaps ? 'all caps reads as spam' : `${caps} CAPS power word(s); top creators use 1–3` });
    const tw = (ctx.trendingWeapons || []).map(norm);
    const wHit = weapons.some(w => tw.includes(norm(w)));
    const topicHits = detectTopics(title).filter(t => (ctx.risingTopics || []).includes(t));
    parts.push({ k: 'Trend match', max: 25, pts: (wHit ? 13 : 0) + (topicHits.length ? 12 : 0), why: [wHit ? 'weapon is hot in this week’s data' : 'weapon isn’t one of this week’s hot picks', topicHits.length ? 'rising topic: ' + topicHits.map(t => TOPIC_BY_ID[t].label).join(', ') : 'no rising topic'].join('; ') });
    const ts = tokenSet(title);
    const simB = Math.max(0, ...(ctx.breakoutTitles || []).map(b => jaccard(ts, tokenSet(b))));
    const simAll = Math.max(0, ...(ctx.realTitles || []).map(b => jaccard(ts, tokenSet(b))));
    const copy = simAll >= 0.75;
    parts.push({ k: 'Breakout pattern', max: 20, pts: copy ? 4 : Math.round(clamp(simB / 0.35) * 20), why: copy ? 'almost identical to an existing title, so change it' : `word overlap with this week’s breakout titles: ${Math.round(simB * 100)}%` });
    const score = parts.reduce((s, p) => s + p.pts, 0);
    return { score, grade: score >= 75 ? 'Strong' : score >= 55 ? 'Good' : score >= 40 ? 'Fair' : 'Weak', parts };
  }
  function rankTitles(titles, ctx) {
    return titles.map(t => String(t).trim()).filter(Boolean).map(t => ({ title: t, ...scoreTitle(t, ctx) })).sort((a, b) => b.score - a.score).map((r, i) => ({ rank: i + 1, ...r }));
  }

  function scoreGroup(list, topic, weapon, ctx) {
    const { cfg, channels, leaving } = ctx;
    const st = groupStats(list, cfg, channels, UMBRELLA.includes(topic));
    const rec = list.filter(v => v.ageHours <= 168);
    const resShare = rec.length ? rec.filter(v => v.resurgence).length / rec.length : 0;
    const fit = (cfg.focus.includes(topic) ? 0.7 : 0.3) + 0.3 * resShare;
    const fading = weapon && leaving.includes(weapon);
    const comp = [
      { k: 'Momentum', max: 30, pts: 30 * clamp((st.momentum - 0.6) / 1.4), why: st.momentumLabel === 'Quiet' ? 'Quiet: no uploads on this in the last 48h' : `${st.momentumLabel}: last-48h uploads beat their norms ${st.momentum}× as strongly as uploads from 2–7 days ago` },
      { k: 'Breakout evidence', max: 25, pts: 25 * clamp(Math.log2(Math.max(st.evidence, 1)) / 3), why: `best videos run ${st.evidence.toFixed(1)}× their channel's typical views (8× = full points)` },
      { k: 'Low competition', max: 20, pts: 20 * (1 - clamp((st.ch48 - 1) / (cfg.saturationChannels - 1))), why: `${st.ch48} channel(s) uploaded this in the last 48h` },
      { k: 'Small-creator proof', max: 15, pts: 15 * clamp(st.smallBreakouts / 2), why: `${st.smallBreakouts} breakout(s) from channels ≤ ${fmtNum(cfg.smallCreatorMaxSubs)} subs` },
      { k: 'Fits your channel', max: 10, pts: 10 * fit, why: `${cfg.focus.includes(topic) ? 'in' : 'outside'} your focus; ${Math.round(resShare * 100)}% of evidence is Rebirth/Resurgence` }
    ].map(p => ({ ...p, pts: Math.round(p.pts) }));
    if (fading) comp.push({ k: 'Being replaced', max: 0, pts: -15, why: `creators are posting “Goodbye ${weapon}” videos` });
    const raw = comp.reduce((s, p) => s + p.pts, 0), cm = st.n7 >= 3 ? 1 : st.n7 === 2 ? 0.8 : 0.6;
    if (cm < 1) comp.push({ k: 'Thin evidence', max: 0, pts: -Math.round(raw * (1 - cm)), why: `only ${st.n7} supporting video${st.n7 === 1 ? '' : 's'} this week, so the score is scaled down` });
    const score = Math.max(0, comp.reduce((s, p) => s + p.pts, 0));
    const verdict = st.saturated || fading ? 'Avoid: saturated or fading' : score >= 65 && st.momentum >= 1 && st.n7 >= 2 ? 'Upload today' : score >= 50 && st.momentum >= 0.9 ? 'Upload in 1–2 days' : 'Wait & watch';
    return { st, comp, score, verdict, confidence: st.n7 >= 5 ? 'Good' : st.n7 >= 3 ? 'Moderate' : 'Low' };
  }

  function buildIdea(c, g, ctx) {
    const { shifts, leaving, titleCtx } = ctx;
    const sup = c.vids.filter(v => v.ageHours <= 168).sort((a, b) => (b.ratio ?? 0) - (a.ratio ?? 0));
    const W = c.weapon || sup.flatMap(v => v.weapons).find(w => !leaving.includes(w)) || null;
    const OLD = (shifts.find(s => s.to === W) || {}).from || null;
    const fill = t => (t.includes('{W}') && !W) || (t.includes('{OLD}') && (!OLD || OLD === W)) ? null : t.replace(/\{W\}/g, W).replace(/\{OLD\}/g, OLD);
    let pool = (TITLE_TEMPLATES[c.topic] || TITLE_TEMPLATES['meta-loadout']).map(fill).filter(Boolean);
    if (pool.length < 3) pool = pool.concat(TITLE_TEMPLATES['meta-loadout'].map(fill).filter(Boolean));
    if (!pool.length) pool = ['XX Kills on Rebirth Island 👑 + #1 Meta Loadout', 'The NEW #1 Meta on Rebirth Island 👑', 'The PERFECT Game on Rebirth Island 👑'];
    const titles = uniq(pool).map(t => ({ title: t, ...scoreTitle(t, titleCtx) })).sort((a, b) => b.score - a.score).slice(0, 3);
    const top = sup[0];
    const why = [
      `${g.st.n7} long-form upload(s) on this in 7 days, ${g.st.n48} in the last 48h from ${g.st.ch48} channel(s).`,
      top && top.ratio != null ? `Strongest: “${top.title}” by ${top.channelTitle}: ${fmtNum(top.views)} views in ${fmtAge(top.ageHours)}, ${top.ratio.toFixed(1)}× that channel's age-adjusted norm.` : '',
      `Momentum: ${g.st.momentumLabel.toLowerCase()} (${g.st.momentum}×).`,
      g.st.smallBreakouts ? `${g.st.smallBreakouts} breakout(s) came from channels under ${fmtNum(ctx.cfg.smallCreatorMaxSubs)} subs, so it isn't just big-creator reach.` : ''
    ].filter(Boolean).join(' ');
    let idea = IDEA_TEMPLATES[c.topic] || IDEA_TEMPLATES['meta-loadout'];
    idea = W ? idea.replace(/\{W\}/g, W) : idea.replace(/ (with|using) the \{W\}|\s?\(\{W\}\)|\{W\}[- ]?/g, '').replace(/\s+/g, ' ').trim();
    idea = idea.charAt(0).toUpperCase() + idea.slice(1);
    return {
      topic: c.topic, topicLabel: TOPIC_BY_ID[c.topic].label, weapon: W, idea, titles,
      thumbnail: (THUMB_TEMPLATES[c.topic] || THUMB_TEMPLATES['meta-loadout']).replace(/\{W\}/g, W || 'your main weapon'),
      why, support: sup.slice(0, 5).map(v => v.id), competition: g.st.competition, momentum: g.st.momentumLabel,
      momentumValue: g.st.momentum, score: g.score, comp: g.comp, verdict: g.verdict, confidence: g.confidence
    };
  }

  function analyze(research, config, history = []) {
    const cfg = mergeConfig(config);
    const nowMs = Date.parse(research.researchedAt);
    const channels = research.channels || {};
    const compiled = compileWeapons(cfg.weapons);
    const resRe = new RegExp(cfg.resurgenceTerms, 'i');
    const exRe = new RegExp(cfg.exclude, 'i');
    const prev = prevSnapshot(history, nowMs);
    const prevAgeH = prev ? (nowMs - Date.parse(prev.at)) / HOUR : null;

    const vids = (research.videos || []).filter(v => v.views != null && !v.live).map(v => {
      const ageHours = Math.max(0.25, (nowMs - Date.parse(v.publishedAt)) / HOUR);
      const isShort = v.durationSec > 0 && v.durationSec <= cfg.shortMaxSeconds;
      const ch = channels[v.channelId] || {};
      let base = isShort ? ch.baselineShort : ch.baselineLong, baseKind = base ? 'median' : null;
      if (!base && !isShort && ch.baselineProxy) { base = ch.baselineProxy; baseKind = 'proxy'; }
      const expected = base ? base.value * expectedFraction(ageHours, cfg.decayDays) : null;
      const ratio = expected ? v.views / expected : null;
      const text = v.title + ' ' + (v.tags || []).join(' ');
      const pv = prev && prev.views && prev.views[v.id];
      const recentVph = pv != null && prevAgeH ? Math.max(0, (v.views - pv) / prevAgeH) : null;
      const g = /goodbye\s+([^,]+),/i.exec(v.title);
      const gone = g ? detectWeapons(g[1], compiled) : [];
      return {
        ...v, ageHours, isShort, vph: v.views / ageHours, recentVph, baseline: base ? base.value : null, baseKind,
        expected, ratio: ratio != null ? +ratio.toFixed(2) : null, lowConfidence: ageHours < 6 || baseKind === 'proxy',
        breakout: ratio != null && ratio >= cfg.breakoutRatio && v.views >= cfg.minBreakoutViews,
        topics: detectTopics(v.title), weapons: detectWeapons(v.title, compiled).filter(w => !gone.includes(w)), kills: detectKills(v.title),
        resurgence: resRe.test(text), tracked: !!ch.tracked, subs: ch.subs ?? null,
        relevant: v.relevant !== false && !exRe.test(v.title)
      };
    });
    const byId = Object.fromEntries(vids.map(v => [v.id, v]));
    const pool = vids.filter(v => v.relevant && (cfg.includeShorts || !v.isShort) && (!cfg.resurgenceOnly || v.resurgence));
    const recent = pool.filter(v => v.ageHours <= 168);
    const histSorted = (history || []).filter(s => Date.parse(s.at) < nowMs - HOUR).sort((a, b) => Date.parse(a.at) - Date.parse(b.at));

    const topics = TOPICS.map(t => {
      const st = groupStats(pool.filter(v => v.topics.includes(t.id)), cfg, channels, UMBRELLA.includes(t.id));
      const prevHeat = prev && prev.topics ? prev.topics[t.id] : null;
      const series = [...histSorted.filter(s => s.topics).map(s => s.topics[t.id] || 0), st.heat];
      return { id: t.id, label: t.label, umbrella: UMBRELLA.includes(t.id), ...st, prevHeat, dayChange: prevHeat ? +(st.heat / prevHeat).toFixed(2) : null, series, ...trendPhase(series) };
    }).sort((a, b) => b.heat - a.heat);

    const wmap = new Map();
    for (const v of pool) for (const w of v.weapons) { const k = norm(w); if (!wmap.has(k)) wmap.set(k, { name: w, vids: [] }); wmap.get(k).vids.push(v); }
    const weapons = [...wmap.values()].map(w => {
      const st = groupStats(w.vids, cfg, channels, false);
      const prevHeat = prev && prev.weapons ? prev.weapons[w.name] : null;
      const series = [...histSorted.filter(s => s.weapons).map(s => s.weapons[w.name] || 0), st.heat];
      return { name: w.name, vids: w.vids, ...st, prevHeat, dayChange: prevHeat ? +(st.heat / prevHeat).toFixed(2) : null, series, ...trendPhase(series) };
    }).filter(w => w.n7 > 0).sort((a, b) => b.heat - a.heat);

    // meta shifts announced in titles: "Goodbye X, Hello Y"
    const shifts = [];
    for (const v of vids.filter(v => v.ageHours <= 21 * 24)) {
      const m = GOODBYE_RE.exec(v.title);
      if (m) shifts.push({ from: detectWeapons(m[1], compiled)[0] || m[1].trim(), to: detectWeapons(m[2], compiled)[0] || m[2].trim(), video: v.id, ageHours: v.ageHours });
    }
    shifts.sort((a, b) => a.ageHours - b.ageHours);
    const leaving = uniq(shifts.filter(s => s.ageHours <= 168).map(s => s.from));

    const breakouts = recent.filter(v => v.breakout).sort((a, b) => b.ratio - a.ratio);

    const cmap = new Map();
    for (const v of recent) { if (!cmap.has(v.channelId)) cmap.set(v.channelId, []); cmap.get(v.channelId).push(v); }
    const creators = [...cmap.entries()].map(([id, vs]) => {
      const ch = channels[id] || { title: vs[0].channelTitle };
      const rs = vs.map(v => v.ratio).filter(x => x != null);
      return {
        id, title: ch.title || vs[0].channelTitle, handle: ch.handle || null, subs: ch.subs ?? null, tracked: !!ch.tracked,
        uploads7: vs.length, views7: vs.reduce((s, v) => s + v.views, 0), bestRatio: rs.length ? Math.max(...rs) : null,
        medianRatio: median(rs), breakouts: vs.filter(v => v.breakout).length, baseline: (ch.baselineLong || ch.baselineProxy || {}).value ?? null,
        baseKind: ch.baselineLong ? 'median' : ch.baselineProxy ? 'proxy' : null,
        best: [...vs].sort((a, b) => (b.ratio ?? 0) - (a.ratio ?? 0))[0].id
      };
    }).filter(c => c.medianRatio != null).sort((a, b) => (b.medianRatio * Math.log10(10 + b.views7)) - (a.medianRatio * Math.log10(10 + a.views7)));
    const suggested = creators.filter(c => !c.tracked && c.uploads7 >= 2 && pool.filter(v => v.channelId === c.id && v.resurgence).length >= 1).slice(0, 12);

    const risingTopics = topics.filter(t => t.momentumLabel === 'Rising' && t.n7 >= 2).map(t => t.id);
    const trendingWeapons = weapons.filter(w => !leaving.includes(w.name)).slice(0, 6).map(w => w.name);
    const titleCtx = { trendingWeapons, risingTopics, breakoutTitles: breakouts.slice(0, 15).map(v => v.title), realTitles: vids.map(v => v.title), compiledWeapons: compiled };
    const ctx = { cfg, channels, leaving, shifts, titleCtx };

    const candidates = [];
    for (const w of weapons) candidates.push({ topic: 'meta-loadout', weapon: w.name, vids: w.vids });
    for (const t of TOPICS.map(t => t.id).filter(t => !UMBRELLA.includes(t))) {
      const tv = pool.filter(v => v.topics.includes(t));
      if (tv.some(v => v.ageHours <= 168)) candidates.push({ topic: t, weapon: null, vids: tv });
      for (const w of weapons.slice(0, 8)) { const both = tv.filter(v => v.weapons.includes(w.name)); if (both.filter(v => v.ageHours <= 168).length >= 2) candidates.push({ topic: t, weapon: w.name, vids: both }); }
    }
    const scored = candidates.map(c => { const g = scoreGroup(c.vids, c.topic, c.weapon, ctx); return (g.st.n7 < 2 && g.st.breakouts < 1) ? null : { c, g }; }).filter(Boolean).sort((a, b) => b.g.score - a.g.score);
    const ideas = [], seen = new Set(), perTopic = {}, perW = {};
    for (const { c, g } of scored) {
      if (ideas.length >= 10) break;
      const idea = buildIdea(c, g, ctx);
      const key = c.topic + '|' + (idea.weapon || '');
      if (seen.has(key) || (perTopic[c.topic] || 0) >= 3 || (idea.weapon && (perW[idea.weapon] || 0) >= 2)) continue;
      if (g.verdict.startsWith('Avoid') && ideas.length < 8) continue;
      seen.add(key); perTopic[c.topic] = (perTopic[c.topic] || 0) + 1; if (idea.weapon) perW[idea.weapon] = (perW[idea.weapon] || 0) + 1;
      ideas.push({ rank: ideas.length + 1, ...idea });
    }

    const avoid = [
      ...topics.filter(t => t.saturated).map(t => ({ label: t.label, why: `${t.ch48} channels uploaded it in 48h and momentum is ${t.momentum}×` })),
      ...weapons.filter(w => w.saturated).map(w => ({ label: w.name, why: `${w.ch48} channels uploaded it in 48h and momentum is ${w.momentum}×` })),
      ...leaving.map(w => ({ label: w, why: `being replaced: “Goodbye ${w}” titles this week` }))
    ];

    return {
      researchedAt: research.researchedAt, prevSnapshotAt: prev ? prev.at : null, quotaUsed: research.quotaUsed,
      counts: { videos: vids.length, recent: recent.length, channels: Object.keys(channels).length, tracked: Object.values(channels).filter(c => c.tracked).length },
      byId, vids, pool, topics, weapons, breakouts, creators, suggested, ideas, avoid, shifts, leaving, titleCtx, cfg, _ctx: ctx
    };
  }

  /** Score one of YOUR OWN ideas (free text) against this week's verified data. */
  function evaluateIdea(text, a) {
    const t = String(text || '').trim();
    if (!t) return null;
    const compiled = a.titleCtx.compiledWeapons;
    const weapons = detectWeapons(t, compiled);
    let topics = detectTopics(t);
    if (!topics.length && weapons.length) topics = ['meta-loadout'];
    const specific = topics.filter(x => !UMBRELLA.includes(x));
    const topic = specific[0] || topics[0] || null;
    const notes = [];
    if (!weapons.length && !topics.length) {
      return { text: t, matched: false, score: null, verdict: 'No match yet', topicLabel: '–', weapon: null, support: [], comp: [], titles: [],
        notes: ['No weapon or topic from this week’s data was recognised. Name a weapon (e.g. “M4 Hurricane”) or a format (movement, settings, sniper, ranked, challenge…). If it’s a brand-new weapon, add it to the weapon list in config.json.'] };
    }
    // evidence: videos sharing the weapon(s), narrowed by the specific topic when that still leaves 2+
    let list = a.pool.filter(v => weapons.length ? v.weapons.some(w => weapons.includes(w)) : v.topics.includes(topic));
    if (weapons.length && specific.length) { const narrow = list.filter(v => specific.some(s => v.topics.includes(s))); if (narrow.filter(v => v.ageHours <= 168).length >= 2) list = narrow; else notes.push(`Few videos combine ${weapons.join(' + ')} with ${specific.map(s => TOPIC_BY_ID[s].label.toLowerCase()).join(', ')}, so it’s scored on the weapon alone.`); }
    const rec = list.filter(v => v.ageHours <= 168);
    if (!rec.length) {
      return { text: t, matched: true, score: null, verdict: 'Untested', topicLabel: topic ? TOPIC_BY_ID[topic].label : '–', weapon: weapons[0] || null, support: [], comp: [], titles: [],
        notes: ['Nobody in this week’s data uploaded this. That can mean an early opportunity or no demand: there’s no evidence either way. Try it as a test video, or check again after the next research run.'] };
    }
    const g = scoreGroup(list, topic || 'meta-loadout', weapons[0] || null, a._ctx);
    const idea = buildIdea({ topic: topic || 'meta-loadout', weapon: weapons[0] || null, vids: list }, g, a._ctx);
    if (a.leaving.some(w => weapons.includes(w))) notes.push('Creators are replacing this weapon right now. Consider the weapon they’re switching to.');
    return { text: t, matched: true, topic, topicLabel: idea.topicLabel, weapon: idea.weapon, score: g.score, verdict: g.verdict, confidence: g.confidence,
      competition: g.st.competition, momentum: g.st.momentumLabel, momentumValue: g.st.momentum, comp: g.comp, support: idea.support, titles: idea.titles, thumbnail: idea.thumbnail, why: idea.why, notes };
  }

  function snapshot(research, analysis) {
    const views = {};
    for (const v of analysis.vids) if (v.ageHours <= 24 * 10) views[v.id] = v.views;
    return {
      date: research.researchedAt.slice(0, 10), at: research.researchedAt,
      topics: Object.fromEntries(analysis.topics.map(t => [t.id, t.heat])),
      weapons: Object.fromEntries(analysis.weapons.slice(0, 25).map(w => [w.name, w.heat])),
      views
    };
  }
  function addSnapshot(history, snap, keepDays = 90) {
    const h = (history || []).filter(s => s.date !== snap.date);
    h.push(snap);
    h.sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
    return h.slice(-keepDays);
  }

  // ---------- daily report (markdown) ----------
  function report(a, opts = {}) {
    const tz = opts.timeZone || undefined;
    const when = new Date(a.researchedAt).toLocaleString('en-US', { timeZone: tz, dateStyle: 'full', timeStyle: 'short' });
    const v = id => a.byId[id];
    const link = x => `[${x.title}](https://www.youtube.com/watch?v=${x.id})`;
    const L = [];
    L.push(`# Resurgence AI: daily report`, `Research completed: **${when}** · ${a.counts.recent} long-form videos from the last 7 days · ${a.counts.channels} channels · ${a.quotaUsed} API quota units`, '');
    L.push(`> Views, dates, titles and links are VERIFIED (YouTube Data API). Multiples, heat and momentum are CALCULATED from that data. Ideas, titles, thumbnails and scores are PREDICTIONS.`, '');
    L.push(`## 1. What's trending in Warzone Resurgence today?`);
    for (const t of a.topics.filter(t => t.n7 && !t.umbrella).slice(0, 5)) L.push(`- **${t.label}**: ${t.momentumLabel} (${t.momentum}×), ${t.n48} uploads in 48h from ${t.ch48} channels, ${t.breakouts} breakout(s)${t.dayChange ? `, heat ${t.dayChange}× vs last snapshot` : ''}`);
    L.push('', `## 2. What weapons are gaining popularity?`);
    const gaining = a.weapons.filter(w => !a.leaving.includes(w.name)).sort((x, y) => y.heat * Math.min(y.momentum, 2) - x.heat * Math.min(x.momentum, 2));
    if (!gaining.length) L.push('- No weapon names detected in recent titles. Add current weapon names to config.json.');
    for (const w of gaining.slice(0, 5)) L.push(`- **${w.name}**: ${w.n7} videos / ${w.ch7} channels this week, ${fmtNum(w.views7)} views, ${w.momentumLabel} (${w.momentum}×)`);
    for (const s of a.shifts.filter(s => s.ageHours <= 168).slice(0, 3)) L.push(`- Meta shift: **${s.from} → ${s.to}** (${link(v(s.video))})`);
    L.push('', `## 3. Which creators are getting the most attention?`);
    for (const c of a.creators.slice(0, 5)) L.push(`- **${c.title}**${c.tracked ? ' (tracked)' : ''}: ${c.uploads7} uploads, ${fmtNum(c.views7)} views this week, median ${c.medianRatio?.toFixed(1)}× their norm, best ${c.bestRatio?.toFixed(1)}×`);
    L.push('', `## 4. What videos are unexpectedly blowing up?`);
    if (!a.breakouts.length) L.push('- No video crossed the breakout threshold in the last 7 days.');
    for (const x of a.breakouts.slice(0, 6)) L.push(`- ${link(x)} by ${x.channelTitle}: ${fmtNum(x.views)} views in ${fmtAge(x.ageHours)} = **${x.ratio}×** its channel's age-adjusted norm (${fmtNum(x.baseline)} typical)${x.lowConfidence ? ' · low confidence' : ''}`);
    L.push('', `## 5. The three best videos to record today`);
    for (const i of a.ideas.slice(0, 3)) {
      L.push(`### #${i.rank} ${i.idea}`, `Opportunity **${i.score}/100** · ${i.verdict} · competition ${i.competition} · momentum ${i.momentum} · data confidence ${i.confidence}`, '', i.why, '');
      L.push(`Supporting videos: ` + i.support.map(id => v(id) ? link(v(id)) : '').filter(Boolean).join(' · '), '');
    }
    L.push(`## 6. Title and thumbnail to use`);
    const best = a.ideas[0];
    if (best) L.push(`- Title: **${best.titles[0]?.title}** (title score ${best.titles[0]?.score}/100; replace XX with your real kill count)`, `- Alternates: ${best.titles.slice(1).map(t => t.title).join(' / ')}`, `- Thumbnail: ${best.thumbnail}`);
    else L.push('- Not enough data yet.');
    L.push('', `## 7. What to avoid`);
    if (!a.avoid.length) L.push(`- Nothing is saturated right now.`);
    for (const t of a.avoid) L.push(`- **${t.label}**: ${t.why}`);
    L.push('', `_YouTube does not expose other creators' impressions, CTR or retention, so none of those are used._`);
    return L.join('\n');
  }

  const api = { DEFAULT_CONFIG, TOPICS, TOPIC_BY_ID, UMBRELLA, TITLE_TEMPLATES, THUMB_TEMPLATES, research, analyze, snapshot, addSnapshot, report, scoreTitle, rankTitles, evaluateIdea, detectWeapons, detectTopics, compileWeapons, expectedFraction, computeBaseline, parseDuration, mergeConfig, fmtNum, fmtAge, esc, median, YTError };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.ResurgenceCore = api;
})(typeof self !== 'undefined' ? self : this);
